-- evt:log
RegisterEvent(25, "Log Computer", function()
    local page = 1
    for n = 1, 5 do
        if IsAtLeast(MapVar(1), n) then page = n + 1 end
    end
    evt.PlaySoundName("xeen_log_chirp", 896, 1088, 1056)
    if page == 1 then
        XeenQuests.hook("dd22.log_page_1")
    elseif page == 2 then
        XeenQuests.hook("dd22.log_page_2")
    elseif page == 3 then
        XeenQuests.hook("dd22.log_page_3")
    elseif page == 4 then
        XeenQuests.hook("dd22.log_page_4")
    elseif page == 5 then
        XeenQuests.hook("dd22.log_page_5")
    elseif page == 6 then
        XeenQuests.hook("dd22.log_page_6")
    end
    SetValue(MapVar(1), page % 6)
end, "Log Computer")

