RegisterEvent(30, "Security Console", function(continueStep)
    local eventId = 30
    if continueStep == 1 then
        evt.SetDoorState(4, DoorAction.Open)
        evt.SetDoorState(5, DoorAction.Open)
        XeenQuests.hook("dd22.security_console")
        evt.SetMapVar("AmbientSound1", 2)
        return
    end
    if continueStep ~= nil then
        return
    end
    if IsQBitSet(QBit(117761)) then
        XeenQuests.hook("dd22.security_console")
        return
    end
    AskChoiceWithAnswerSteps(eventId, 3, "Security lockdown: bridge sealed. Release?", {{Answer = "Yes", Step = 1}, {Answer = "No", Step = 2}})
end, "Security Console")
